// Read each source directly via $() — avoids cartesian-product merge confusion
const offre   = $('Query Offre').first().json;
const fciRows = $('Query FCI Outputs').all().map(i => i.json);
const winRateRows = (() => { try { return $('Query Win Rate FOR-COM').all().map(i => i.json); } catch(e) { return []; } })();
const kbRows      = (() => { try { return $('Query KB Stats').all().map(i => i.json); } catch(e) { return []; } })();
const corrRows    = (() => { try { return $('Query Corrections Stats').all().map(i => i.json); } catch(e) { return []; } })();

const winRate = winRateRows[0] ?? null;
const kb      = kbRows[0]     ?? {};
const corr    = corrRows[0]   ?? {};

// Index FCI outputs by departement
const fciByDept = {};
for (const row of fciRows) {
  fciByDept[row.departement] = row;
}

const avis    = d => { const r = fciByDept[d]; if (!r) return 'Non soumis'; const m = {favorable:'FAVORABLE',reserve:'RÉSERVÉ',defavorable:'DÉFAVORABLE'}; return m[r.avis] ?? r.avis ?? 'En attente'; };
const comment = d => fciByDept[d]?.commentaires ?? 'Aucun commentaire';
const valideur = d => fciByDept[d]?.valide_par  ?? 'Non validé';

// Parse donnees_brutes
const brutes = offre.donnees_brutes ?? {};
const txt     = v => Array.isArray(v) ? v.filter(Boolean).join('\n') : (v ?? 'À compléter');
const bullets = v => Array.isArray(v) ? v.filter(Boolean).map(x => '• ' + x).join('\n') : (v ?? 'À compléter');

const winRateStr = winRate
  ? `${winRate.winrate_pct ?? '?'}% (${winRate.total_gagnes ?? 0} gagné(s) / ${winRate.total_perdus ?? 0} perdu(s) sur ${winRate.total_offres ?? 0} offres)`
  : 'Aucun historique disponible pour ce client';

const alertes = brutes?.flags?.alertes ?? [];
const alertesStr = alertes.length > 0 ? alertes.map(a => '⚠ ' + a).join('\n') : 'Aucune alerte détectée sur ce CDC';

const nbKb = parseInt(kb.nb_patterns_kb ?? 0);
const statutApprentissage = nbKb === 0 ? 'Amorçage (aucun pattern)'
  : nbKb < 5  ? `Démarrage (${nbKb} patterns)`
  : `Actif (${nbKb} patterns, dont ${kb.nb_patterns_fiables ?? 0} fiables)`;

const codeClean = (offre.code_offre ?? 'SANS_CODE').replace(/[^a-zA-Z0-9_-]/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,'');
const clientClean = (offre.client ?? 'CLIENT').replace(/[^a-zA-Z0-9_-]/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,'');
const outputSubfolder = `C:\\Users\\lotfi\\.n8n-files\\Concept\\gonogo\\output\\${codeClean}`;
const fileName = `FOR_COM_02_${clientClean}_${codeClean}.docx`;
const filePath = `${outputSubfolder}\\${fileName}`;

// Create output subfolder (mkdirSync)
const fs   = require('fs');
const path = require('path');
try { fs.mkdirSync(outputSubfolder, { recursive: true }); } catch(e) { /* exists or will fail on write */ }

const data = {
  offre_id:          String(offre.offre_id ?? offre.id ?? ''),
  code_offre:        offre.code_offre        ?? 'À compléter',
  intitule:          offre.intitule          ?? 'À compléter',
  client:            offre.client            ?? 'À compléter',
  financement:       offre.financement       ?? 'À compléter',
  budget:            offre.budget            ?? 'À compléter',
  type_offre:        offre.type_offre        ?? 'À compléter',
  methode_selection: offre.methode_selection ?? 'À compléter',
  date_cloture:      offre.date_cloture      ?? 'À compléter',
  date_generation:   new Date().toLocaleDateString('fr-FR', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}),
  avis_commercial:   avis('commercial'), avis_operations: avis('operations'),
  avis_finance:      avis('finance'),    avis_dg: avis('dg'), avis_groupement: avis('groupement'),
  commentaires_commercial: comment('commercial'), commentaires_operations: comment('operations'),
  commentaires_finance:    comment('finance'),    commentaires_dg: comment('dg'), commentaires_groupement: comment('groupement'),
  valide_par_commercial:   valideur('commercial'), valide_par_operations: valideur('operations'),
  valide_par_finance:      valideur('finance'),    valide_par_dg: valideur('dg'), valide_par_groupement: valideur('groupement'),
  win_rate:             winRateStr,
  nb_patterns_kb:       String(nbKb),
  statut_apprentissage: statutApprentissage,
  nb_corrections:       String(corr.nb_corrections ?? 0),
  alertes:              alertesStr,
  forces:       bullets(brutes?.analyse?.forces),
  faiblesses:   bullets(brutes?.analyse?.faiblesses),
  opportunites: bullets(brutes?.analyse?.opportunites),
  menaces:      bullets(brutes?.analyse?.menaces),
  risques:      bullets(brutes?.risques_majeurs),
  personnel_cle: bullets(brutes?.donnees_techniques?.personnel_cle),
  modalites_paiement: txt(brutes?.donnees_financieres?.modalites_paiement ?? offre.modalites_paiement),
  decision: 'En attente de signature DG', conditions_motifs: '', signe_par: '', date_decision: '',
  statut_bdd: 'Enregistré',
};

return [{ json: { data, meta: { offre_id: offre.offre_id ?? offre.id, codeClean, clientClean, outputSubfolder, fileName, filePath } } }];

const PizZip = require('pizzip');
const Docxtemplater = require('docxtemplater');

const templateBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const { data, meta } = $('Build FOR-COM-02 Data').first().json;

const zip = new PizZip(templateBuffer);
const doc = new Docxtemplater(zip, { paragraphLoop: true, linebreaks: true });
doc.render(data);
const out = doc.getZip().generate({ type: 'nodebuffer' });

return [{
  json: { generated: true, fileName: meta.fileName, filePath: meta.filePath, offre_id: meta.offre_id },
  binary: {
    data: await this.helpers.prepareBinaryData(
      out,
      meta.fileName,
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    )
  }
}];

